export const navIndustries = industries
  .filter((i) => i.slug !== 'cosmetics')
  .map((i) => ({
  name: i.name,
  slug: i.slug,
  icon: i.icon,
}))

export function getIndustryBySlug(slug: string): Industry | undefined {
  return industries.find((i) => i.slug === slug)
}
